def get_prime_powers(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            factors[d] = d**count
        d += 1
    if temp > 1:
        factors[temp] = temp
    return list(factors.values())

