for diff in range(7975, -1, -1):
    beta_min = diff + 2025
    beta_max = 10000
    if beta_min > beta_max:
        continue

    found = False
    for beta in range(beta_min, beta_max + 1):
        c = 2 * beta - diff
        prime_powers = get_prime_powers(c)
        valid = True
        for pp in prime_powers:
            if a1 % pp != 0 and (a1 + beta) % pp != 0:
                valid = False
                break
        if valid:
            found = True
            break
    if found:
        max_diff = diff
        break

